from typing import Any

class Paint:
    BLACK     = "\033[30m"
    RED       = "\033[31m"
    GREEN     = "\033[32m"
    YELLOW    = "\033[33m"
    BLUE      = "\033[34m"
    MAGENTA   = "\033[35m"
    CYAN      = "\033[36m"
    WHITE     = "\033[37m"

    BOLD      = "\033[1m"
    ITALIC    = "\033[3m"
    UNDERLINE = "\033[4m"

    RESET     = "\033[0m"

    def __init__(self, parsed_string: str, end: str):
        self.parsed_string = parsed_string
        self.end = end
        self.codes = []

    def show(self):
        print(self, end=self.end)

    def black(self):
        self.codes.append(Paint.BLACK)
        return self

    def red(self):
        self.codes.append(Paint.RED)
        return self

    def green(self):
        self.codes.append(Paint.GREEN)
        return self

    def yellow(self):
        self.codes.append(Paint.YELLOW)
        return self

    def blue(self):
        self.codes.append(Paint.BLUE)
        return self

    def magenta(self):
        self.codes.append(Paint.MAGENTA)
        return self

    def cyan(self):
        self.codes.append(Paint.CYAN)
        return self

    def white(self):
        self.codes.append(Paint.WHITE)
        return self

    def bold(self):
        self.codes.append(Paint.BOLD)
        return self

    def underline(self):
        self.codes.append(Paint.UNDERLINE)
        return self

    def italic(self):
        self.codes.append(Paint.ITALIC)
        return self

    def __str__(self) -> str:
        codes = self.codes
        codes.extend([self.parsed_string, Paint.RESET])
        final_string = "".join(codes)
        return final_string

def paint(*args: Any, sep=" ", end="\n") -> Paint:
    parsed_string = sep.join(map(str, args))
    return Paint(parsed_string, end)
